import 'dart:convert';
import 'package:flutter/material.dart';

class MecityLogo extends StatelessWidget {
  final double size;
  final bool hasGlow;

  const MecityLogo({
    super.key,
    this.size = 38,
    this.hasGlow = true,
  });

  static const String _logoBase64 = '';

  @override
  Widget build(BuildContext context) {
    return Container(
      width: size,
      height: size,
      decoration: BoxDecoration(
        shape: BoxShape.circle,
        boxShadow: hasGlow
            ? [
                BoxShadow(
                  color: const Color(0xFFD4AF37).withValues(alpha: 0.4),
                  blurRadius: size * 0.25,
                  spreadRadius: 1,
                ),
              ]
            : null,
      ),
      child: ClipOval(
        child: Image.memory(
          base64Decode(_logoBase64),
          fit: BoxFit.cover,
          width: size,
          height: size,
        ),
      ),
    );
  }
}
